function generateMockSeasons(item: any) {
  const numSeasons = parseInt(item.duration) || 1;
  const seasons = [];
  for (let s = 1; s <= numSeasons; s++) {
    const numEpisodes = 10;
    const episodes = [];
    for (let e = 1; e <= numEpisodes; e++) {
      episodes.push({
        id: `ep-${item.tmdbId}-${s}-${e}`,
        episodeNumber: e,
        seasonNumber: s,
        title: `Episódio ${e}`,
        overview: `Descrição detalhada do episódio ${e} da Temporada ${s} de ${item.title}. Assista agora em HD.`,
        duration: '45m',
        thumbnailUrl: item.backdropUrl || item.posterUrl,
      });
    }
    seasons.push({
      seasonNumber: s,
      title: `Temporada ${s}`,
      episodesCount: numEpisodes,
      episodes,
    });
  }
  return seasons;
}

export function generate1000Movies(): Movie[] {
  const result: Movie[] = [...CURATED_TITLES];
  const seenIds = new Set<number>(CURATED_TITLES.map((m) => m.tmdbId));
  const seenStringIds = new Set<string>(CURATED_TITLES.map((m) => m.id));

  AUTHENTIC_TITLES_DATA.forEach((item) => {
    if (!seenIds.has(item.tmdbId)) {
      seenIds.add(item.tmdbId);

      let generatedId = `${item.type === 'tv' ? 's' : 'm'}-${item.tmdbId}`;
      if (seenStringIds.has(generatedId)) {
        generatedId = `${item.type === 'tv' ? 's' : 'm'}-auth-${item.tmdbId}`;
      }
      seenStringIds.add(generatedId);

      result.push({
        id: generatedId,
        tmdbId: item.tmdbId,
        imdbId: `tt${item.tmdbId + 100000}`,
        title: item.title,
        originalTitle: item.originalTitle || item.title,
        overview: item.overview,
        posterUrl: item.posterUrl,
        backdropUrl: item.backdropUrl,
        releaseYear: item.year,
        rating: item.rating,
        matchScore: Math.min(99, Math.floor(item.rating * 10 + 8)),
        ageRating: item.ageRating,
        duration: item.duration,
        type: item.type,
        genres: item.genres,
        cast: item.cast,
        director: item.director,
        tags: [item.type === 'tv' ? 'Série' : 'Filme', ...item.genres],
        isNetflixOriginal: item.isNetflixOriginal || false,
        isTrending: item.isTrending || item.rating >= 8.4,
        seasonsCount: item.type === 'tv' ? parseInt(item.duration) || 1 : undefined,
        seasons: item.type === 'tv' ? generateMockSeasons(item) : undefined,
      });
    }
  });

  return result;
}

export const MOVIES_1000_DATABASE = generate1000Movies();
